# name: perfect_alternation_vs_long_runs
# description: The mean probability of choosing the left sequence when it is perfectly alternating (p_alts=1) and the right sequence has long runs (max_run >= 4).
def test_statistic(df):
    mask = (df['p_alts_a'] == 1.0) & (df['max_run_b'] >= 4)
    if not mask.any(): return 0.0
    return float(df.loc[mask, 'chose_left'].mean())

# name: moderate_vs_high_alternation
# description: The mean probability of choosing the left sequence when it has moderate alternation (0.4-0.6) and the right has high (>0.8).
def test_statistic(df):
    mask = (df['p_alts_a'] >= 0.4) & (df['p_alts_a'] <= 0.6) & (df['p_alts_b'] > 0.8)
    if not mask.any(): return 0.0
    return float(df.loc[mask, 'chose_left'].mean())

# name: rep_motifs_aversion
# description: The mean probability of choosing the left sequence when it has strictly more repeating motifs than the right sequence.
def test_statistic(df):
    mask = df['rep_motifs_a'] > df['rep_motifs_b']
    if not mask.any(): return 0.0
    return float(df.loc[mask, 'chose_left'].mean())

